// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/deps.ts`. Edit the source and run `just generate`.
// The rules of `dotclaude-spec deps`: the waves, the blocked chains, and the `owns` overlaps of a change.

import { CLOSED_LANES, type Lane } from "../../../kernel/spec-store.ts";
import { ownsOverlap } from "./validate.ts";

/** One package of the graph: its id, its wave, its deps, and its `owns`. */
export interface Node {
  readonly id: string;
  readonly wave: number;
  readonly deps: readonly string[];
  readonly owns: readonly string[];
}

/** The lanes that stop the packages that depend on a package. */
const STOPPING: readonly Lane[] = ["blocked", "canceled"];

/** The ids of `nodes` by wave, in the order of the waves and of `nodes`. */
export const wavesOf = (
  nodes: readonly Node[],
): { wave: number; ids: string[] }[] =>
  [...new Set(nodes.map((n) => n.wave))]
    .sort((a, b) => a - b)
    .map((wave) => ({
      wave,
      ids: nodes.filter((n) => n.wave === wave).map((n) => n.id),
    }));

/**
 * The blocked chains: for each open package that depends, at any depth, on a `blocked` or `canceled` package,
 * the path of ids from the package to the first such dep.
 */
export const blockedChains = (
  nodes: readonly Node[],
  lanes: Readonly<Record<string, Lane>>,
): string[][] => {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const chainFrom = (id: string, seen: Set<string>): string[] | null => {
    for (const dep of byId.get(id)?.deps ?? []) {
      if (seen.has(dep)) continue;
      const lane = lanes[dep];
      if (lane !== undefined && STOPPING.includes(lane)) return [id, dep];
      const rest = chainFrom(dep, new Set([...seen, dep]));
      if (rest) return [id, ...rest];
    }
    return null;
  };
  const ended: readonly Lane[] = [...CLOSED_LANES, ...STOPPING];
  return nodes
    .filter((n) => !ended.includes(lanes[n.id] ?? "planned"))
    .map((n) => chainFrom(n.id, new Set([n.id])))
    .filter((chain) => chain !== null);
};

/** The pairs of open packages of one wave whose `owns` overlap, in the order of `nodes`. */
export const ownsOverlaps = (
  nodes: readonly Node[],
  lanes: Readonly<Record<string, Lane>>,
): [string, string][] => {
  const open = nodes.filter(
    (n) => !CLOSED_LANES.includes(lanes[n.id] ?? "planned"),
  );
  const pairs: [string, string][] = [];
  for (const [i, a] of open.entries())
    for (const b of open.slice(i + 1))
      if (a.wave === b.wave && ownsOverlap([...a.owns], [...b.owns]))
        pairs.push([a.id, b.id]);
  return pairs;
};
